class Graph {
 int n;vector<vector<pair<int,int>>> g;
public:
 Graph(int n,vector<vector<int>>& edges):n(n),g(n){for(auto &e:edges)addEdge(e);}
 void addEdge(vector<int> edge){g[edge[0]].push_back({edge[1],edge[2]});}
 int shortestPath(int node1,int node2){
  const long long INF=LLONG_MAX/4;vector<long long> dist(n,INF);
  using P=pair<long long,int>;priority_queue<P,vector<P>,greater<P>> pq;
  dist[node1]=0;pq.push({0,node1});
  while(!pq.empty()){
   auto cur=pq.top();pq.pop();long long d=cur.first;int u=cur.second;
   if(d!=dist[u])continue;if(u==node2)return (int)d;
   for(auto e:g[u])if(dist[e.first]>d+e.second){dist[e.first]=d+e.second;pq.push({dist[e.first],e.first});}
  }return -1;
 }
};
